import unittest
import dotted_key as app

class Behavior(unittest.TestCase):
    def test_key_parts(self):
        rows=[('dock.port',['dock','port']),(' dock . port ',['dock','port']),('site."dock.net".port',['site','dock.net','port']),("site.'a.b'",['site','a.b']),('"".port',['','port']),('3.14159',['3','14159']),('"a\\u002eb".c',['a.b','c']),('"a\\"b".c',['a"b','c']),('site."雪"',['site','雪'])]
        for s,w in rows:self.assertEqual(app.key_parts(s),w)


if __name__ == "__main__":
    unittest.main()

class LiteralKeyEdges(unittest.TestCase):
    def test_single_and_literal_keys(self):
        self.assertEqual(app.key_parts('harbor'), ['harbor'])
        self.assertEqual(app.key_parts("site.'C:\\new.a'"), ['site', 'C:\\new.a'])
        self.assertEqual(app.key_parts('site."a=b#c"'), ['site', 'a=b#c'])
        self.assertEqual(app.key_parts("'' . ''"), ['', ''])
